from bisect import bisect_left


def minCopiesForSubsequence(source, target):
    pos = {}
    for i, c in enumerate(source):
        pos.setdefault(c, []).append(i)
    copies = 1
    cur = 0
    for c in target:
        lst = pos.get(c)
        if lst is None:
            return -1
        k = bisect_left(lst, cur)
        if k == len(lst):
            copies += 1
            k = 0
        cur = lst[k] + 1
    return copies
